questionvariables.text:
/* Intervals in degrees. The identity is undefined where sin(theta) = 0. */
ivL: [[0, 360], [-180, 180], [90, 450], [-360, 0], [-90, 270], [0, 540]];
ivpick: rand(ivL);
lo: ivpick[1];
hi: ivpick[2];
ta1: setify(sublist(makelist(t, t, lo, hi), lambda([t], is(mod(t, 180) = 0))));
/* Diagnostics: the zeros of cos; both kinds; some values missing; a value outside the interval. */
cpts: setify(sublist(makelist(t, t, lo, hi), lambda([t], is(mod(t, 180) = 90))));
dboth: union(ta1, cpts);
dpart: setdifference(ta1, {lmin(listify(ta1))});
dout: union(ta1, {lo - 180});
s_assert(is(cardinality(dpart) > 0), true);
validate_degset(ex) := if not(setp(ex)) then "Type a set in curly brackets, for example {30, 45}, or {} for no values."
  else if not(freeof(%pi, ex)) then "Give the angles in degrees: do not use pi."
  else if not(every(lambda([v], numberp(ev(v, simp))), listify(ex))) then "Type numbers only."
  else "";
